// Storage keys in localStorage
const STORAGE_KEYS = {
  SUBMISSIONS: "silan_submissions_v2",
  USERS: "silan_users_v2",
  VISITORS: "silan_visitors_v2",
  CURRENT_USER: "silan_current_user_v2",
  SYSTEM_TEXTS: "silan_system_texts_v2"
};

function getStoredSubmissions() {
  const data = localStorage.getItem(STORAGE_KEYS.SUBMISSIONS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.SUBMISSIONS, JSON.stringify(INITIAL_SUBMISSIONS));
    return INITIAL_SUBMISSIONS;
  }
  try {
    return JSON.parse(data);
  } catch (e) {
    return INITIAL_SUBMISSIONS;
  }
}

function saveStoredSubmissions(submissions) {
  localStorage.setItem(STORAGE_KEYS.SUBMISSIONS, JSON.stringify(submissions));
}

function getStoredUsers() {
  const data = localStorage.getItem(STORAGE_KEYS.USERS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(INITIAL_USERS));
    return INITIAL_USERS;
  }
  try {
    return JSON.parse(data);
  } catch (e) {
    return INITIAL_USERS;
  }
}

function saveStoredUsers(users) {
  localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
}

function getStoredVisitors() {
  const data = localStorage.getItem(STORAGE_KEYS.VISITORS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.VISITORS, JSON.stringify(INITIAL_VISITORS));
    return INITIAL_VISITORS;
  }
  try {
    return JSON.parse(data);
  } catch (e) {
    return INITIAL_VISITORS;
  }
}

function saveStoredVisitors(visitors) {
  localStorage.setItem(STORAGE_KEYS.VISITORS, JSON.stringify(visitors));
}

function getStoredCurrentUser() {
  const data = localStorage.getItem(STORAGE_KEYS.CURRENT_USER);
  if (!data) {
    return null;
  }
  try {
    return JSON.parse(data);
  } catch (e) {
    return null;
  }
}

function saveStoredCurrentUser(user) {
  if (user) {
    localStorage.setItem(STORAGE_KEYS.CURRENT_USER, JSON.stringify(user));
  } else {
    localStorage.removeItem(STORAGE_KEYS.CURRENT_USER);
  }
}

function getStoredSystemTexts() {
  const data = localStorage.getItem(STORAGE_KEYS.SYSTEM_TEXTS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.SYSTEM_TEXTS, JSON.stringify(DEFAULT_SYSTEM_TEXTS));
    return { ...DEFAULT_SYSTEM_TEXTS };
  }
  try {
    return { ...DEFAULT_SYSTEM_TEXTS, ...JSON.parse(data) };
  } catch (e) {
    return { ...DEFAULT_SYSTEM_TEXTS };
  }
}

function saveStoredSystemTexts(texts) {
  localStorage.setItem(STORAGE_KEYS.SYSTEM_TEXTS, JSON.stringify(texts));
}

function resetToDefaultData() {
  localStorage.setItem(STORAGE_KEYS.SUBMISSIONS, JSON.stringify(INITIAL_SUBMISSIONS));
  localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(INITIAL_USERS));
  localStorage.setItem(STORAGE_KEYS.VISITORS, JSON.stringify(INITIAL_VISITORS));
  localStorage.setItem(STORAGE_KEYS.SYSTEM_TEXTS, JSON.stringify(DEFAULT_SYSTEM_TEXTS));
  localStorage.removeItem(STORAGE_KEYS.CURRENT_USER);
}

// RESTful Database Client Bridge (SQLite Sync with LocalStorage Fallback)
const DataAPI = {
  isOnline: true,

  async init() {
    try {
      const res = await fetch('/api/stats');
      if (res.ok) {
        const json = await res.json();
        if (json.success) {
          this.isOnline = true;
          // Synchronize submissions
          const subRes = await fetch('/api/submissions?limit=1000');
          if (subRes.ok) {
            const subData = await subRes.json();
            if (subData.success && subData.data.length > 0) {
              saveStoredSubmissions(subData.data);
            }
          }
        }
      }
    } catch (e) {
      this.isOnline = false;
    }
  },

  async addSubmission(sub) {
    if (this.isOnline) {
      try {
        await fetch('/api/submissions', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(sub)
        });
      } catch (e) {
        console.warn('API sync warning:', e);
      }
    }
  },

  async updateSubmission(id, updateData) {
    if (this.isOnline) {
      try {
        await fetch(`/api/submissions/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(updateData)
        });
      } catch (e) {
        console.warn('API sync warning:', e);
      }
    }
  },

  async deleteSubmission(id) {
    if (this.isOnline) {
      try {
        await fetch(`/api/submissions/${id}`, {
          method: 'DELETE'
        });
      } catch (e) {
        console.warn('API sync warning:', e);
      }
    }
  },

  async saveSettings(settings) {
    if (this.isOnline) {
      try {
        await fetch('/api/settings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(settings)
        });
      } catch (e) {
        console.warn('API sync warning:', e);
      }
    }
  }
};

// Initialize background sync on load
if (typeof window !== 'undefined') {
  window.addEventListener('DOMContentLoaded', () => {
    DataAPI.init();
  });
}

